<script setup lang="ts">import{ref,onMounted}from 'vue';import{useRouter}from 'vue-router';import{samples,loadBatches}from '../stores/samples';import{runs,loadRuns}from '../stores/runs';import{createRun}from '../api/runs';import{canEdit}from '../stores/auth';import{useTask}from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import BatchSelect from '../components/BatchSelect.vue';import RunTable from '../components/RunTable.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';const router=useRouter();const form=ref({name:'11月城区出行 · 代表性校准',batch_id:1,tolerance:.0001,max_iterations:500,cap_ratio:12});const{error,busy,execute}=useTask();const refresh=()=>execute(async()=>{await Promise.all([loadBatches(),loadRuns()])});const submit=()=>execute(async()=>{const r=await createRun(form.value);await router.push('/results/'+r.id)});onMounted(refresh);</script><template><PageHeading index="04" title="一次可复算的权重迭代" subtitle="逐维调整类别权重，保留每一步残差及截断对收敛的影响。"/><ErrorNotice :message="error" @retry="refresh"/><div class="workbench"><form v-if="canEdit" @submit.prevent="submit"><h2>建立校准运行</h2><label>研究名称<input v-model="form.name" required minlength="2" maxlength="100"/></label><BatchSelect v-model="form.batch_id" :items="samples.batches"/><div class="form-grid"><label>归一残差容差<input v-model.number="form.tolerance" type="number" min=".000001" max=".05" step=".000001" required/></label><label>最多迭代次数<input v-model.number="form.max_iterations" type="number" min="1" max="2000" required/></label></div><label>权重上限 / 目标平均权重的倍数<input v-model.number="form.cap_ratio" type="number" min="1" max="30" step=".1" required/></label><button class="primary" :disabled="busy">{{busy?'正在排队…':'提交后台校准 →'}}</button></form><aside><p class="eyebrow">METHOD / BOUNDED RAKING</p><h2>边际收敛，<br>不等于消除了全部偏差。</h2><p>每轮依次校准年龄组、出行方式和分区，再截断权重。上限太低或交叉结构不兼容时，可能无法收敛。</p><p>Kish有效样本量反映权重离散的代价；它不包含聚类、分层或未观测选择偏差。</p><p>未收敛运行可查看诊断，负责人不能批准交付。</p></aside></div><div class="section-heading"><h2>迭代档案</h2><button @click="refresh">刷新 ↻</button></div><RunTable :items="runs.items"/></template>
